import {Component, inject, OnInit} from '@angular/core';
import {ActivatedRoute, Router} from '@angular/router';
import {$$, getParams, setParams, showMessage} from '../../tools';
import {MatButton} from '@angular/material/button';
import {TokemonComponent} from '../tokemon/tokemon.component';
import {UserService} from '../user.service';
import {environment} from '../../environments/environment';
import {HourglassComponent, wait_message} from '../hourglass/hourglass.component';
import {createTokenTransfer, get_nft, query, send_transaction_with_transfers} from '../mvx';
import {MatDialog} from '@angular/material/dialog';
import {DecimalPipe, Location, NgIf} from '@angular/common';
import {InputComponent} from '../input/input.component';
import {TokenTransfer} from '@multiversx/sdk-core/out';
import {eval_direct_url_xportal} from '../../crypto';
import {DeviceService} from '../device.service';
import {ApiService} from '../api.service';
import {cartesianToPolar, Point3D, polarToCartesian} from '../tokenworld';
import {MatSnackBar} from '@angular/material/snack-bar';
import {settings} from '../../environments/settings';

@Component({
  selector: 'app-capture',
  standalone: true,
  imports: [
    MatButton,
    TokemonComponent,
    HourglassComponent,
    NgIf,
    InputComponent,
    DecimalPipe
  ],
  templateUrl: './capture.component.html',
  styleUrl: './capture.component.css'
})
export class CaptureComponent implements OnInit {
  item: any;
  api=inject(ApiService)
  _location=inject(Location)
  chance_to_win: number=1

  dialog=inject(MatDialog)
  toast=inject(MatSnackBar)
  routes = inject(ActivatedRoute)
  user = inject(UserService)
  router=inject(Router)
  device=inject(DeviceService)

  message: string=""
  max_engagment: number=100
  pv_to_engage: number=0
  target=new Point3D(0,0,0)
  bags: any[]=[];
  nft:any



  async ngOnInit() {
    let params:any = await getParams(this.routes)
    this.item=params.item
    this.target=params.target
    try{
      this.bags=await query("get_tokemon_bags",[this.item.id],this.user.get_sc_address(),this.user.network)

      await this.user.login(this,"","",true,0.01,"You must buy some egld to pay fee for fight or capture tokemon")
      this.user.init_game(Number(params.game))

      let pv=this.user.tokens[this.user.pv_token]
      if(!pv || pv.balance==0){
        showMessage(this,"You can't fight without HP token")
        this.quit("faucet","You must buy some HealthPoint ("+this.user.pv_token+") token to fight in "+settings.appname)
      }

      if(this.item.owner!=this.user.idx && this.item.pv>0){
        this.label="Fight"
        this.pv_to_engage=1
      }

      $$("Tentative de capture du tokemon ",this.item)

      // @ts-ignore
      this.lang_pv=environment.dictionnary[this.user.lang || "en"].pv
    }catch (e){
      this.quit()
    }

  }

  quit(dest="map",message=""){
    setTimeout(()=>{
      this.router.navigate([dest],{queryParams:{message:message}})
    },500)

  }

  async on_capture() {
    let captured_tokemon:any=null
    if(this.user.game){
      try {
        let func_name=this.pv_to_engage>0 ? "capture" : "take"

        let args=[this.user.game.id,Number(this.item.id),this.target.x,this.target.y,this.target.z]
        wait_message(this, func_name=='capture' ? "Fighting ... " : "Capturing ...")
        let tokens=[]
        if(this.pv_to_engage>0)tokens.push(createTokenTransfer(this.user.pv_token,this.pv_to_engage)[0])
        $$("Appel de la "+func_name+" with ",args)
        let rc:any = await send_transaction_with_transfers(
          this.user,
          func_name,
          args,
          tokens);

        if(rc.returnCode=="ok"){
          $$("Resultat ",rc)
          captured_tokemon=rc.values[0]
          if(func_name=="capture") {
            showMessage(this, captured_tokemon.owner == this.user.idx ? "You win the fight" : "Sorry, you loose the fight")
          }else{
            showMessage(this,"The tokemon return to your wallet as an NFT. You recover its HP and bag")
          }
        }else{
          showMessage(this,"Technical error, please try again")
        }

      } catch (e){
        showMessage(this,"Technical problem, please try again")
      }
      wait_message(this);
      setTimeout(()=>{
        let pos=cartesianToPolar(captured_tokemon.position,environment.scale_factor,environment.translate_factor)
        this.router.navigate(["map"],{queryParams:{lat:pos.lat,lng:pos.lng,zoom:18}})},1000)
    }

  }

  cancel() {
    this._location.back()
  }

  update_value($event: any) {
    this.pv_to_engage=Number($event)
    let y=Number(this.item.pv)
    let x=this.pv_to_engage
    let proba=(x)/(y+x)   //(y+1-(x-1)/2)/y
    this.chance_to_win=Math.round(proba*100.0)
  }

  protected readonly environment = environment;
  lang_pv: string="HP"
  label: string="Capture"

  open_xportal() {
    open(eval_direct_url_xportal(this.user.provider.uri))
  }

  refund(revitalize:boolean) {
    let coin_to_use=this.user.pv_token
    let args: any=revitalize ? {token:this.item,coin:coin_to_use} : {token:this.item}
    this.router.navigate(["refund"],{queryParams:{p:setParams(args,"","")}})
  }
}
