import {Component, inject, OnInit} from '@angular/core';
import {environment} from "../../environments/environment";
import {MatExpansionPanel, MatExpansionPanelHeader} from "@angular/material/expansion";
import {NgForOf, NgIf} from "@angular/common";
import {ApiService} from "../api.service";
import {MatTab, MatTabGroup} from "@angular/material/tabs";
import {MatButton} from "@angular/material/button";
import {showMessage} from "../../tools";
import {MatDialog} from "@angular/material/dialog";
import {_prompt} from "../prompt/prompt.component";
import {InputComponent} from "../input/input.component";
import {UserService} from "../user.service";
import {query, toText} from "../mvx";
import {cartesianToPolar, polarToCartesian} from '../tokenworld';

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [
    MatExpansionPanel, MatExpansionPanelHeader,
    NgForOf, MatTabGroup, MatTab, MatButton, InputComponent, NgIf
  ],
  templateUrl: './admin.component.html',
  styleUrl: './admin.component.css'
})
export class AdminComponent implements OnInit {

  protected readonly environment = environment;
  models: string[]=[];

  api=inject(ApiService)
  dialog=inject(MatDialog)
  user=inject(UserService)

  infos: any;
  sel_model: any;
  options=[{label:"Main network",value:"mainnet"},{label:"Beta network",value:"devnet"},{label:"Test network",value:"testnet"}]
  sel_network=this.options[1]
  nfts:any[]=[]

  async refresh(){
    this.nfts=[]
    for(let nft of await query("tokemons",[],this.user.get_sc_address(),this.user.network)){
      nft.coords=cartesianToPolar(nft,environment.scale_factor)
      this.nfts.push(nft)
    }

  }

  ngOnInit(): void {
    this.user.login(this,"","",true)
    this.refresh()
  }


  async add_model() {
    let model_to_add=await _prompt(this,"Ajouter un modele","","Donner le nom du modèle (voir sur hugging-face","text","Ajouter","Annuler",false)
    this.api._get(environment.server+"/load_model","model="+model_to_add).subscribe(()=>{
      showMessage(this,"Modele ajouté")
      this.refresh()
    })
  }





  update_network($event: any) {
    this.user.logout()
    this.user.network=$event.value
    this.sel_network=$event
  }

  update_expert_mode($event: any) {
    this.user.expert_mode=$event
    localStorage.setItem("expert_mode",$event ? "true" : "false")
  }

  protected readonly TextDecoder = TextDecoder;
  protected readonly toText = toText;
  protected readonly latLonToCartesian = polarToCartesian;
  protected readonly cartesianToPolar = cartesianToPolar;
}
